    "[your name]": "[اسمك]",
    "iMessage: turn on Contact Key Verification": "iMessage: فعّل التحقق من مفتاح جهة الاتصال",
    "iOS 26 and iOS 18": "iOS 26 وiOS 18",
    "iOS Updates": "تحديثات iOS",
